mapper.select:
SELECT DISTINCT 

FROM review_tasks rt
LEFT JOIN review_task_assignments rta ON rt.id = rta.review_task_id
WHERE rt.creator_id = #{userId} 
   OR rta.expert_id = #{userId}
ORDER BY rt.created_at DESC

    LIMIT #{limit}

SELECT 
    rt.status,
    COUNT(*) as count
FROM review_tasks rt


        AND rt.creator_id = #{creatorId}


        AND rt.project_id = #{projectId}


        AND rt.created_at >= #{startDate}


        AND rt.created_at <= #{endDate}


GROUP BY rt.status

SELECT rt.priority, COUNT(*) as count FROM review_tasks rt WHERE rt.status NOT IN ('COMPLETED', 'CANCELLED', 'ARCHIVED')
AND rt.creator_id = #{creatorId}
GROUP BY rt.priority

