SET status = #{status}, 
    updated_at = NOW(),
    updated_by = #{updatedBy}
WHERE id = #{id}

UPDATE review_tasks 
SET progress_data = #{progressData}, 
    updated_at = NOW(),
    updated_by = #{updatedBy}
WHERE id = #{id}

